// Daily backlog run for Aozora Line, run by .github/workflows/daily.yml through actions/github-script.
//
// Two jobs, both plain rules so they are cheap and unit-tested (tests/daily.spec.js):
//   1. Veto window: a `proposed` task becomes `ready` once it has carried the `proposed` label for
//      36 hours with no veto: no `hold` or `needs-yes` label and no "no" / "drop" comment from the
//      owner. At most 3 tasks a day, oldest first. Big changes (controls, modes, the real-world route,
//      prod) carry `needs-yes` and wait for the owner's yes.
//   2. Friday report: on Fridays (New York time) it opens one `report` issue: shipped, proposed, blocked,
//      play links and 4 numbers. The coordinator summarises it in the project chat.
// Reviews are not done here: a daily scheduled Claude run reviews PRs half an hour earlier, at 7:00 New York time (docs/REVIEW.md).

const PROPOSED = 'proposed';
const READY = 'ready';
const VETO_LABELS = ['hold', 'needs-yes'];
const REPORT_LABEL = 'report';
const WINDOW_HOURS = 36;
const MAX_PER_DAY = 3;
const PROMOTED_MARKER = '<!-- backlog: promoted -->';
const OWNER_ROLES = ['OWNER'];
// A comment by the owner that starts with "no", "nope" or "drop" vetoes ("No thanks", "Drop it",
// "drop #12"); "No problem" and "No worries" do not. A missed veto matters more than an extra one.
// Claude's comments are posted from the owner's account, so ones carrying its footer never count.
const VETO_COMMENT = /^\s*(no|nope|drop)\b/i;
const NOT_A_VETO = /^\s*no\s+(problem|problems|worries)\b/i;
const CLAUDE_FOOTER = /_Generated by \[Claude Code\]/;
const TIME_ZONE = 'America/New_York'; // the owner's day and week (Hitoshi's choice, 2026-11-10)
const BOTS = ['github-actions[bot]'];
// Files that change what players see or hear.
const PLAYER_FACING = [/^game\.js$/, /^src\//, /^style\.css$/, /^index\.html$/, /^assets\//];

const HOUR = 3600 * 1000;
const labelNames = (issue) => (issue.labels || []).map((l) => (typeof l === 'string' ? l : l.name));

// The newest time the `proposed` label was added, from the issue's events (falls back to creation).
function proposedAt(issue, events) {
  let at = null;
  for (const e of events || []) {
    if (e.event === 'labeled' && e.label && e.label.name === PROPOSED) at = e.created_at;
  }
  return new Date(at || issue.created_at);
}

// Why a proposed task may not be promoted yet, or null when it may.
function vetoReason(issue, comments, since, now) {
  const labels = labelNames(issue);
  if (issue.pull_request) return 'is a PR';
  if (issue.state && issue.state !== 'open') return 'closed';
  if (!labels.includes(PROPOSED)) return `not labelled ${PROPOSED}`;
  if (labels.includes(READY)) return `already ${READY}`;
  const veto = labels.find((l) => VETO_LABELS.includes(l));
  if (veto) return `labelled ${veto}`;
  const no = (comments || []).find((c) => OWNER_ROLES.includes(c.author_association) &&
    !BOTS.includes(c.user && c.user.login) && !CLAUDE_FOOTER.test(c.body || '') && VETO_COMMENT.test(c.body || '') && !NOT_A_VETO.test(c.body || ''));
  if (no) return 'the owner said no';
  const hours = (now - since) / HOUR;
  if (hours < WINDOW_HOURS) return `in the veto window (${Math.floor(hours)} of ${WINDOW_HOURS} h)`;
  return null;
}

// Picks the tasks to promote now. `candidates` is [{ issue, comments, since }].
// `promotedToday` counts tasks this rule already promoted in the last 24 hours.
function promotions(candidates, now, promotedToday = 0) {
  const room = Math.max(0, MAX_PER_DAY - promotedToday);
  const promote = [];
  const skipped = [];
  const sorted = [...candidates].sort((a, b) => a.since - b.since);
  for (const c of sorted) {
    const why = vetoReason(c.issue, c.comments, c.since, now);
    if (why) skipped.push({ number: c.issue.number, reason: why });
    else if (promote.length < room) promote.push(c.issue.number);
    else skipped.push({ number: c.issue.number, reason: `daily limit of ${MAX_PER_DAY} reached` });
  }
  return { promote, skipped };
}

// Promotions this rule made in the last 24 hours, from the marker comment it leaves.
function countPromoted(commentsByIssue, now) {
  let n = 0;
  for (const comments of commentsByIssue) {
    if ((comments || []).some((c) => (c.body || '').includes(PROMOTED_MARKER) &&
      now - new Date(c.created_at) < 24 * HOUR)) n += 1;
  }
  return n;
}

// New York calendar date (YYYY-MM-DD) and weekday (0 Sunday … 5 Friday) of a moment.
function localDay(now) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
  }).formatToParts(now).map((p) => [p.type, p.value]));
  const weekday = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(parts.weekday);
  return { date: `${parts.year}-${parts.month}-${parts.day}`, weekday };
}
const isReportDay = (now) => localDay(now).weekday === 5;

// The issue number a PR closes ("Closes #12", "Fixes #3"), or null.
function closesIssue(body) {
  const m = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s+#(\d+)/i.exec(body || '');
  return m ? Number(m[1]) : null;
}

const playerFacing = (files) => (files || []).some((f) => PLAYER_FACING.some((re) => re.test(f.filename || f)));

function median(xs) {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

// The 4 weekly numbers. `merged` is [{ number, files, mergedBy, mergedAt, readyAt }] for PRs merged
// this week (readyAt: when the issue it closes got `ready`, or null). `ownerMessages` counts the
// owner's messages this week (rows dated this week in the REQUIREMENTS.md feedback log).
function metrics(merged, ownerMessages) {
  const n = merged.length;
  const leads = merged.filter((p) => p.readyAt).map((p) => (new Date(p.mergedAt) - new Date(p.readyAt)) / HOUR);
  const lead = median(leads);
  return {
    messagesPerPr: n ? Math.round((ownerMessages / n) * 10) / 10 : null,
    mergedWithoutOwner: merged.filter((p) => BOTS.includes(p.mergedBy)).length,
    leadTimeHours: lead === null ? null : Math.round(lead * 10) / 10,
    playerFacingShare: n ? Math.round((merged.filter((p) => playerFacing(p.files)).length / n) * 100) : null,
    merged: n,
  };
}

// Feedback-log rows (| YYYY-MM-DD | ... |) dated within [from, to] (New York dates, inclusive), from
// REQUIREMENTS.md ("## 3. Feedback log") or docs/feedback-archive.md ("## Feedback log, older rows").
function feedbackRows(markdown, from, to) {
  const section = (markdown || '').split(/^## (?:\d+\. )?Feedback log.*$/m)[1] || '';
  const body = section.split(/^## /m)[0];
  return body.split('\n').filter((line) => {
    const m = /^\|\s*(\d{4}-\d{2}-\d{2})\s*\|/.exec(line);
    return m && m[1] >= from && m[1] <= to;
  }).length;
}

// The play-link lines between the README markers.
function playLinks(readme) {
  const m = /<!-- play-links:start -->\n([\s\S]*?)\n<!-- play-links:end -->/.exec(readme || '');
  return m ? m[1].trim() : '- See README.md';
}

const show = (v, unit = '') => (v === null || v === undefined ? 'n/a' : `${v}${unit}`);
const list = (items, empty) => (items.length ? items.map((i) => `- ${i}`).join('\n') : `- ${empty}`);

// The report issue body.
function reportBody({ weekOf, shipped, proposed, blocked, links, numbers }) {
  return [
    `Week to ${weekOf} (New York time). Written by the daily backlog run; the coordinator summarises it in the project chat.`,
    '', '## Shipped to dev', list(shipped, 'Nothing merged this week.'),
    '', '## Proposed (becomes ready after 36 h unless vetoed: `hold`, "no" or "drop #N")', list(proposed, 'Nothing proposed.'),
    '', '## Blocked or waiting', list(blocked, 'Nothing blocked.'),
    '', '## Play links', links,
    '', '## Numbers',
    '| Measure | This week |', '|---|---|',
    `| Hitoshi's messages per shipped PR | ${show(numbers.messagesPerPr)} |`,
    `| PRs merged with no message from Hitoshi (merged by the queue, no "m") | ${numbers.mergedWithoutOwner} of ${numbers.merged} |`,
    `| Lead time, task \`ready\` to dev (median) | ${show(numbers.leadTimeHours, ' h')} |`,
    `| Player-facing share of PRs (change game.js, src/, style.css, index.html or assets) | ${show(numbers.playerFacingShare, '%')} |`,
    '', '_Messages are counted from the REQUIREMENTS.md feedback log, which records every message from Hitoshi._',
  ].join('\n');
}

async function ensureLabels(github, owner, repo) {
  const want = {
    [PROPOSED]: ['c5def5', 'Proposed by Claude; becomes ready after 36 h unless vetoed'],
    'needs-yes': ['d93f0b', 'Big change (controls, modes, route, prod): waits for the owner\'s yes'],
    [REPORT_LABEL]: ['0e8a16', 'Weekly report'],
  };
  for (const [name, [color, description]] of Object.entries(want)) {
    try { await github.rest.issues.getLabel({ owner, repo, name }); } catch {
      await github.rest.issues.createLabel({ owner, repo, name, color, description });
    }
  }
}

async function promote({ github, owner, repo, now, say }) {
  const issues = await github.paginate(github.rest.issues.listForRepo, {
    owner, repo, state: 'open', labels: PROPOSED, per_page: 100,
  });
  const candidates = [];
  for (const issue of issues.filter((i) => !i.pull_request)) {
    const events = await github.paginate(github.rest.issues.listEvents, { owner, repo, issue_number: issue.number, per_page: 100 });
    const comments = await github.paginate(github.rest.issues.listComments, { owner, repo, issue_number: issue.number, per_page: 100 });
    candidates.push({ issue, comments, since: proposedAt(issue, events) });
  }
  const recent = await github.paginate(github.rest.issues.listForRepo, {
    owner, repo, state: 'all', labels: READY, since: new Date(now - 24 * HOUR).toISOString(), per_page: 100,
  });
  const recentComments = [];
  for (const issue of recent) {
    recentComments.push(await github.paginate(github.rest.issues.listComments, {
      owner, repo, issue_number: issue.number, since: new Date(now - 24 * HOUR).toISOString(), per_page: 100,
    }));
  }
  const { promote: numbers, skipped } = promotions(candidates, now, countPromoted(recentComments, now));
  for (const n of numbers) {
    await github.rest.issues.addLabels({ owner, repo, issue_number: n, labels: [READY] });
    try { await github.rest.issues.removeLabel({ owner, repo, issue_number: n, name: PROPOSED }); } catch { /* already gone */ }
    await github.rest.issues.createComment({
      owner, repo, issue_number: n,
      body: `No veto in ${WINDOW_HOURS} hours, so this task is now \`${READY}\`. ${PROMOTED_MARKER}`,
    });
    say(`#${n}: promoted to ${READY}.`);
  }
  for (const s of skipped) say(`#${s.number}: stays ${PROPOSED} (${s.reason}).`);
  return { numbers, skipped };
}

async function report({ github, owner, repo, now, say }) {
  const { date } = localDay(now);
  const title = `Weekly report, week to ${date}`;
  const existing = await github.paginate(github.rest.issues.listForRepo, {
    owner, repo, state: 'all', labels: REPORT_LABEL, per_page: 100,
  });
  if (existing.some((i) => i.title === title)) { say(`${title} already exists.`); return null; }

  const weekStart = new Date(now - 7 * 24 * HOUR);
  const fromDate = localDay(new Date(weekStart.getTime() + 24 * HOUR)).date; // the 7 days after last week's report
  const closed = await github.paginate(github.rest.pulls.list, {
    owner, repo, state: 'closed', base: 'main', sort: 'updated', direction: 'desc', per_page: 100,
  });
  const merged = [];
  for (const pr of closed.filter((p) => p.merged_at && new Date(p.merged_at) > weekStart)) {
    const { data: full } = await github.rest.pulls.get({ owner, repo, pull_number: pr.number });
    const files = await github.paginate(github.rest.pulls.listFiles, { owner, repo, pull_number: pr.number, per_page: 100 });
    let readyAt = null;
    const issueNo = closesIssue(pr.body);
    if (issueNo) {
      const events = await github.paginate(github.rest.issues.listEvents, { owner, repo, issue_number: issueNo, per_page: 100 });
      const ready = events.find((e) => e.event === 'labeled' && e.label && e.label.name === READY);
      readyAt = ready ? ready.created_at : null;
    }
    merged.push({
      number: pr.number, title: pr.title, files, mergedAt: pr.merged_at, readyAt,
      mergedBy: full.merged_by && full.merged_by.login,
    });
  }
  const read = async (path) => {
    const { data } = await github.rest.repos.getContent({ owner, repo, path, ref: 'main' });
    return Buffer.from(data.content, 'base64').toString('utf8');
  };
  // REQUIREMENTS.md keeps the latest 20 rows; older ones move to the archive.
  const ownerMessages = feedbackRows(await read('REQUIREMENTS.md'), fromDate, date) +
    feedbackRows(await read('docs/feedback-archive.md'), fromDate, date);
  const proposedIssues = await github.paginate(github.rest.issues.listForRepo, {
    owner, repo, state: 'open', labels: PROPOSED, per_page: 100,
  });
  const openIssues = await github.paginate(github.rest.issues.listForRepo, { owner, repo, state: 'open', per_page: 100 });
  const blocked = openIssues
    .filter((i) => labelNames(i).some((l) => ['hold', 'needs-yes', 'queue-conflict'].includes(l)))
    .map((i) => `#${i.number} ${i.title} (${labelNames(i).filter((l) => ['hold', 'needs-yes', 'queue-conflict'].includes(l)).join(', ')})`);
  const body = reportBody({
    weekOf: date,
    shipped: merged.map((p) => `#${p.number} ${p.title}`),
    proposed: proposedIssues.filter((i) => !i.pull_request).map((i) => `#${i.number} ${i.title}`),
    blocked,
    links: playLinks(await read('README.md')),
    numbers: metrics(merged, ownerMessages),
  });
  const { data: issue } = await github.rest.issues.create({ owner, repo, title, body, labels: [REPORT_LABEL] });
  say(`Opened ${title} (#${issue.number}).`);
  return issue.number;
}

async function run({ github, context, core, now = new Date(), forceReport = false }) {
  const { owner, repo } = context.repo;
  const lines = [];
  const say = (msg) => { core.info(msg); lines.push(msg); };
  await ensureLabels(github, owner, repo);
  await promote({ github, owner, repo, now, say });
  if (forceReport || isReportDay(now)) await report({ github, owner, repo, now, say });
  else say('Not Friday in New York: no weekly report today.');
  await core.summary.addHeading('Daily backlog run').addList(lines.length ? lines : ['Nothing to do.']).write();
}

module.exports = {
  run, proposedAt, vetoReason, promotions, countPromoted, localDay, isReportDay, closesIssue, playerFacing,
  metrics, feedbackRows, playLinks, reportBody, WINDOW_HOURS, MAX_PER_DAY, PROMOTED_MARKER,
};
